 21	const O_WRONLY = 1;
 22	const LIBC: Partial<Record<NodeJS.Platform, string>> = {
 23	  linux: "libc.so.6",
 24	  darwin: "libSystem.B.dylib",
 25	};
 26	
 27	let libc: Libc | null | undefined;
 28	let depth = 0;
 29	let savedFd = -1;
 30	
 31	function loadLibc(): Libc | null {
 32	  if (libc !== undefined) return libc;
 33	  libc = null;
 34	  const name = LIBC[process.platform];
 35	  if (!name) return libc;
 36	  try {
 37	    const koffi = createRequire(import.meta.url)("koffi") as typeof import("koffi");
 38	    const lib = koffi.load(name);
 39	    libc = {
 40	      dup: lib.func("int dup(int)"),
 41	      dup2: lib.func("int dup2(int, int)"),
 42	      close: lib.func("int close(int)"),
 43	      open: lib.func("int open(const char *, int)"),
 44	    };
 45	  } catch {
 46	    // koffi or libc unavailable: leave stderr alone.
 47	  }
 48	  return libc;
 49	}
 50	
 51	function silence(c: Libc): void {
 52	  if (depth++ > 0) return;
 53	  const saved = c.dup(2);
 54	  if (saved < 0) return;
 55	  const nul = c.open("/dev/null", O_WRONLY);
 56	  if (nul < 0) {
 57	    c.close(saved);
 58	    return;
 59	  }
 60	  c.dup2(nul, 2);
 61	  c.close(nul);
 62	  savedFd = saved;
 63	}
 64	
 65	function restore(c: Libc): void {
 66	  if (--depth > 0 || savedFd < 0) return;
 67	  c.dup2(savedFd, 2);
 68	  c.close(savedFd);
 69	  savedFd = -1;
 70	}
