 75	 * back to just running `fn` where the redirect is not possible.
 76	 */
 77	export async function withSilencedNativeStderr<T>(fn: () => Promise<T>): Promise<T> {
 78	  const c = process.env.PI_PII_REDACT_NATIVE_LOGS ? null : loadLibc();
 79	  if (!c) return fn();
 80	  silence(c);
 81	  try {
 82	    return await fn();
 83	  } finally {
 84	    restore(c);
 85	  }
 86	}
