    83	              const body = ["", ...renderStatsLines(data, { width: Number.POSITIVE_INFINITY, style }), ""];
    84	              let offset = 0;
    85	              /** Body rows that fit: terminal height minus borders, hint and a little margin. */
    86	              const visibleRows = () => Math.max(3, (tui?.terminal?.rows ?? 24) - 5);
    87	              const scroll = (delta: number) => {
    88	                const max = Math.max(0, body.length - visibleRows());
