   113	                  };
   114	                  return [
   115	                    theme.fg("border", `╭${"─".repeat(innerW)}╮`),
   116	                    ...shown.map(row),
   117	                    row(hint),
   118	                    theme.fg("border", `╰${"─".repeat(innerW)}╯`),
   119	                  ];
   120	                },
   121	                invalidate() {},
   122	              };
   123	            },
