/** Per-call options. */
export interface CallOptions {
  /** @deprecated Has no effect. */
  group?: string;
  /** The end-user device for this call; resolved per call. Licensing does not read it yet. */
  deviceId?: string | (() => string);
}

/** A loaded model behind an opaque core handle: what a model package's public
 *  class delegates to, identical on both runtimes. */
export class LoadedModel {
  /** The model's own input payload in, its own result payload out: one shape for
   *  every modality. */
  run(input: Uint8Array, options: Uint8Array, call?: CallOptions): Promise<FfiReader>;
  isDownloaded(): boolean;
  /** @deprecated Has no effect: runs `body` with a group id that nothing reads. */
  withCallGroup<T>(body: (group: string) => Promise<T>): Promise<T>;
  /** Wait for the license requests in flight. */
  flushTelemetry(): Promise<boolean>;
  dispose(): void;
}

/** How a model is loaded, shared by both runtimes. A model package extends this
 *  with its own inference options. */
export interface ModelLoadOptions {
  directory?: string;
  modelBaseUrl?: string;
